window.docContents[179].resolve({"/Output-Formats/#html-conventions":{"contents":"While Verso genres may generate whatever output is necessary, some aspects of the Verso infrastructure make assumptions about generated HTML.\nIn particular, Verso assumes that HTML follows these conventions:* Each page contains a <base> tag that points at the site root, and all URLs are relative to the site root.* Pages are served as directories that contain an index.html file, rather than as bare HTML files. In other words, instead of page.html, the page should be served as page/index.html. This affects the meaning of relative URLs.\n\n\n\n\n\n\n\n","context":"Writing Documentation in Lean with Verso\u0009Output Formats\u0009HTML","header":"5.1.1. Conventions","id":"/Output-Formats/#html-conventions"}});